-- Baseline: database/schema/02-schema.sql as it was before the code-editor
-- preference was added.
--
-- Do not run this file on a database that already has the schema. Existing
-- databases mark it as applied and then apply the later migrations:
--
--   ./database/atlas.sh migrate set 20261020150022 --url "$DATABASE_URL"
--   ./database/atlas.sh migrate apply --url "$DATABASE_URL"
--
-- A database created from the current schema file is stamped at the latest
-- version instead. See database/README.md.

-- Create enum type "user_t"
CREATE TYPE "user_t" AS ENUM ('student', 'professor', 'admin', 'dev');
-- Create enum type "commit_exercise_test_case_status_t"
CREATE TYPE "commit_exercise_test_case_status_t" AS ENUM ('killed_with_signal', 'correct', 'bad_formatted_output');
-- Create enum type "alert_recipients_t"
CREATE TYPE "alert_recipients_t" AS ENUM ('students', 'professors', 'monitors', 'all');
-- Create enum type "enrollment_role_t"
CREATE TYPE "enrollment_role_t" AS ENUM ('student', 'professor', 'monitor');
-- Create enum type "exercise_type_t"
CREATE TYPE "exercise_type_t" AS ENUM ('programming');
-- Create enum type "input_output_type_t"
CREATE TYPE "input_output_type_t" AS ENUM ('text', 'file');
-- Create enum type "commit_status_t"
CREATE TYPE "commit_status_t" AS ENUM ('pending', 'queued', 'compiling', 'compilation_error', 'running', 'completed', 'uncompleted', 'server_error', 'plagiarism', 'timeout');
-- Create "system_disk_reports" table
CREATE TABLE "system_disk_reports" ("id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY, "disk_name" text NOT NULL, "total_space_kb" bigint NOT NULL, "used_space_kb" bigint NOT NULL, "free_space_kb" bigint NOT NULL, "report_time" timestamptz NOT NULL DEFAULT now(), PRIMARY KEY ("id"));
-- Create enum type "alert_type_t"
CREATE TYPE "alert_type_t" AS ENUM ('info', 'warning', 'danger', 'success');
-- Create "mail_logs" table
CREATE TABLE "mail_logs" ("id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY, "sent_to" text NOT NULL, "subject" text NOT NULL, "message" text NOT NULL, "hash" text NOT NULL, "sent_at" timestamptz NOT NULL DEFAULT now(), PRIMARY KEY ("id"));
-- Create "users" table
CREATE TABLE "users" ("id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY, "name" text NOT NULL, "email" text NOT NULL, "org_id" text NULL, "password_hash" text NOT NULL, "role" "user_t" NOT NULL DEFAULT 'student', "confirmed" boolean NOT NULL DEFAULT false, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), PRIMARY KEY ("id"), CONSTRAINT "users_email_key" UNIQUE ("email"), CONSTRAINT "users_org_id_key" UNIQUE ("org_id"));
-- Create "platform_settings" table
CREATE TABLE "platform_settings" ("key" text NOT NULL, "value" text NOT NULL, "updated_at" timestamptz NOT NULL DEFAULT now(), PRIMARY KEY ("key"));
-- Create "offerings" table
CREATE TABLE "offerings" ("id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY, "name" text NOT NULL, "owner_id" integer NULL, "end_date" timestamptz NOT NULL, "visible_to_enroll" boolean NOT NULL DEFAULT true, "enrollment_code" text NULL, "description" text NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), PRIMARY KEY ("id"), CONSTRAINT "offerings_enrollment_code_key" UNIQUE ("enrollment_code"), CONSTRAINT "offerings_owner_id_fkey" FOREIGN KEY ("owner_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "idx_offerings_owner_id" to table: "offerings"
CREATE INDEX "idx_offerings_owner_id" ON "offerings" ("owner_id");
-- Create "alerts" table
CREATE TABLE "alerts" ("id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY, "type" "alert_type_t" NOT NULL, "recipients" "alert_recipients_t" NOT NULL, "offering_id" integer NULL, "user_id" integer NULL, "valid_until" timestamptz NOT NULL, "title" text NOT NULL, "message" text NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "read" boolean NOT NULL DEFAULT false, PRIMARY KEY ("id"), CONSTRAINT "alerts_offering_id_fkey" FOREIGN KEY ("offering_id") REFERENCES "offerings" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "alerts_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "idx_alerts_offering_id" to table: "alerts"
CREATE INDEX "idx_alerts_offering_id" ON "alerts" ("offering_id");
-- Create index "idx_alerts_user_id" to table: "alerts"
CREATE INDEX "idx_alerts_user_id" ON "alerts" ("user_id");
-- Create "exercises" table
CREATE TABLE "exercises" ("id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY, "offering_id" integer NULL, "creator_id" integer NULL, "title" text NOT NULL, "description" text NULL, "deadline" timestamptz NOT NULL, "type" "exercise_type_t" NOT NULL DEFAULT 'programming', "open_date" timestamptz NOT NULL, "show_before_open_date" boolean NOT NULL DEFAULT false, "removed" boolean NOT NULL DEFAULT false, "ghost" boolean NOT NULL DEFAULT false, "real_id" integer NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), PRIMARY KEY ("id"), CONSTRAINT "exercises_creator_id_fkey" FOREIGN KEY ("creator_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "exercises_offering_id_fkey" FOREIGN KEY ("offering_id") REFERENCES "offerings" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "idx_exercises_creator_id" to table: "exercises"
CREATE INDEX "idx_exercises_creator_id" ON "exercises" ("creator_id");
-- Create index "idx_exercises_offering_id" to table: "exercises"
CREATE INDEX "idx_exercises_offering_id" ON "exercises" ("offering_id");
-- Create "commits" table
CREATE TABLE "commits" ("id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY, "user_id" integer NULL, "exercise_id" integer NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "status" "commit_status_t" NOT NULL DEFAULT 'pending', "num_correct_cases" integer NOT NULL DEFAULT 0, "score" numeric(5,2) NOT NULL DEFAULT 0, "compiled" boolean NULL, "compilation_message" text NULL, "compilation_started" timestamptz NULL, "compilation_finished" timestamptz NULL, "compilation_error" text NULL, "ip" inet NULL, "s3_key" text NULL, PRIMARY KEY ("id"), CONSTRAINT "commits_exercise_id_fkey" FOREIGN KEY ("exercise_id") REFERENCES "exercises" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "commits_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "commits_score_check" CHECK ((score >= (0)::numeric) AND (score <= (100)::numeric)));
-- Create index "idx_commits_exercise_id" to table: "commits"
CREATE INDEX "idx_commits_exercise_id" ON "commits" ("exercise_id");
-- Create index "idx_commits_queued" to table: "commits"
CREATE INDEX "idx_commits_queued" ON "commits" ("created_at") WHERE (status = 'queued'::commit_status_t);
-- Create index "idx_commits_user_id" to table: "commits"
CREATE INDEX "idx_commits_user_id" ON "commits" ("user_id");
-- Create "exercises_test_cases" table
CREATE TABLE "exercises_test_cases" ("id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY, "exercise_id" integer NULL, "input" text NOT NULL, "input_type" "input_output_type_t" NOT NULL, "show_input" boolean NOT NULL DEFAULT true, "expected_output" text NOT NULL, "expected_output_type" "input_output_type_t" NOT NULL, "show_expected_output" boolean NOT NULL DEFAULT true, "show_user_output" boolean NOT NULL DEFAULT true, "cpu_time_limit_seconds" integer NOT NULL, "mem_usage_limit_bytes" integer NOT NULL, "stack_limit_bytes" integer NOT NULL, "file_size_limit_bytes" integer NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), PRIMARY KEY ("id"), CONSTRAINT "exercises_test_cases_exercise_id_fkey" FOREIGN KEY ("exercise_id") REFERENCES "exercises" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "idx_exercises_test_cases_exercise_id" to table: "exercises_test_cases"
CREATE INDEX "idx_exercises_test_cases_exercise_id" ON "exercises_test_cases" ("exercise_id");
-- Create "commits_exercise_test_cases_results" table
CREATE TABLE "commits_exercise_test_cases_results" ("commit_id" integer NOT NULL, "exercise_test_case_id" integer NOT NULL, "cpu_time" numeric(15,4) NOT NULL, "mem_usage" integer NOT NULL, "user_output" text NULL, "user_output_type" "input_output_type_t" NOT NULL, "status" "commit_exercise_test_case_status_t" NOT NULL, "status_message" text NULL, "error_message" text NULL, PRIMARY KEY ("commit_id", "exercise_test_case_id"), CONSTRAINT "commits_exercise_test_cases_results_commit_id_fkey" FOREIGN KEY ("commit_id") REFERENCES "commits" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "commits_exercise_test_cases_results_exercise_test_case_id_fkey" FOREIGN KEY ("exercise_test_case_id") REFERENCES "exercises_test_cases" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "idx_results_exercise_test_case_id" to table: "commits_exercise_test_cases_results"
CREATE INDEX "idx_results_exercise_test_case_id" ON "commits_exercise_test_cases_results" ("exercise_test_case_id");
-- Create "enrollments" table
CREATE TABLE "enrollments" ("user_id" integer NOT NULL, "offering_id" integer NOT NULL, "role" "enrollment_role_t" NOT NULL, "banned" boolean NOT NULL DEFAULT false, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), PRIMARY KEY ("user_id", "offering_id"), CONSTRAINT "enrollments_offering_id_fkey" FOREIGN KEY ("offering_id") REFERENCES "offerings" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "enrollments_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "idx_enrollments_offering_id" to table: "enrollments"
CREATE INDEX "idx_enrollments_offering_id" ON "enrollments" ("offering_id");
-- Create "allowed_file_types" table
CREATE TABLE "allowed_file_types" ("id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY, "name" text NOT NULL, "extension" text NOT NULL, "is_compilable" boolean NOT NULL DEFAULT true, "is_available" boolean NOT NULL DEFAULT true, PRIMARY KEY ("id"), CONSTRAINT "allowed_file_types_extension_key" UNIQUE ("extension"), CONSTRAINT "allowed_file_types_name_key" UNIQUE ("name"));
-- Create "exercises_allowed_file_types" table
CREATE TABLE "exercises_allowed_file_types" ("exercise_id" integer NOT NULL, "allowed_file_type_id" integer NOT NULL, PRIMARY KEY ("exercise_id", "allowed_file_type_id"), CONSTRAINT "exercises_allowed_file_types_allowed_file_type_id_fkey" FOREIGN KEY ("allowed_file_type_id") REFERENCES "allowed_file_types" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "exercises_allowed_file_types_exercise_id_fkey" FOREIGN KEY ("exercise_id") REFERENCES "exercises" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "idx_exercises_allowed_file_types_type_id" to table: "exercises_allowed_file_types"
CREATE INDEX "idx_exercises_allowed_file_types_type_id" ON "exercises_allowed_file_types" ("allowed_file_type_id");
-- Create "exercises_attached_files" table
CREATE TABLE "exercises_attached_files" ("id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY, "exercise_id" integer NULL, "path" text NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "exercises_attached_files_exercise_id_fkey" FOREIGN KEY ("exercise_id") REFERENCES "exercises" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "idx_exercises_attached_files_exercise_id" to table: "exercises_attached_files"
CREATE INDEX "idx_exercises_attached_files_exercise_id" ON "exercises_attached_files" ("exercise_id");
-- Create "exercises_compilation_files" table
CREATE TABLE "exercises_compilation_files" ("id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY, "exercise_id" integer NULL, "path" text NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "exercises_compilation_files_exercise_id_fkey" FOREIGN KEY ("exercise_id") REFERENCES "exercises" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "idx_exercises_compilation_files_exercise_id" to table: "exercises_compilation_files"
CREATE INDEX "idx_exercises_compilation_files_exercise_id" ON "exercises_compilation_files" ("exercise_id");
-- Create "exercises_test_cases_files" table
CREATE TABLE "exercises_test_cases_files" ("id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY, "exercise_test_case_id" integer NULL, "path" text NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "exercises_test_cases_files_exercise_test_case_id_fkey" FOREIGN KEY ("exercise_test_case_id") REFERENCES "exercises_test_cases" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "idx_exercises_test_cases_files_case_id" to table: "exercises_test_cases_files"
CREATE INDEX "idx_exercises_test_cases_files_case_id" ON "exercises_test_cases_files" ("exercise_test_case_id");
-- Create "system_logs" table
CREATE TABLE "system_logs" ("id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY, "user_id" integer NULL, "log_time" timestamptz NOT NULL DEFAULT now(), "ip" inet NOT NULL, "action" text NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "system_logs_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "idx_system_logs_user_id" to table: "system_logs"
CREATE INDEX "idx_system_logs_user_id" ON "system_logs" ("user_id");
-- Create "user_messages" table
CREATE TABLE "user_messages" ("id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY, "user_id" integer NULL, "recipes" text NOT NULL, "subject" text NOT NULL, "message" text NOT NULL, "attachments" text NULL, "template" text NULL, "created_at" timestamptz NOT NULL DEFAULT now(), PRIMARY KEY ("id"), CONSTRAINT "user_messages_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "idx_user_messages_user_id" to table: "user_messages"
CREATE INDEX "idx_user_messages_user_id" ON "user_messages" ("user_id");
